" height=\"35\" rx=\"3.5\" fill=\"currentColor\" fill-opacity=\".14\"/><rect x=\"9\" y=\"4.5\" width=\"30\" height=\"35\" rx=\"3.5\"/><rect x=\"15\" y=\"10\" width=\"18\" height=\"10.5\" rx=\"1.8\" fill=\"currentColor\" fill-opacity=\".22\"/><path d=\"M15.5 30c2-3.4 4.1-3.4 6.1 0s4.1 3.4 6.1 0 4.1-3.4 6.1 0M15 39.5v4M33 39.5v4M24 39.5v3\"/></symbol><symbol id=\"i-kit\" viewBox=\"0 0 48 48\"><path d=\"M6.5 6h22l-2.6 15.5H3.9z\" fill=\"currentColor\" fill-opacity=\".16\"/><path d=\"M6.5 6h22l-2.6 15.5H3.9zM13.9 6l-1.5 15.5M21.2 6l-.8 15.5M5.4 13.7h22M12 21.5v6M8 27.5h8\"/><rect x=\"30\" y=\"20.5\" width=\"13.5\" height=\"22\" rx=\"2.6\" fill=\"currentColor\" fill-opacity=\".16\"/><rect x=\"30\" y=\"20.5\" width=\"13.5\" height=\"22\" rx=\"2.6\"/><path d=\"M34 17.5h5.5M38 25.5l-3 5h4l-3 5\" stroke-width=\"2.4\"/><path d=\"M12 27.5v9.5h18\"/></symbol><symbol id=\"i-module\" viewBox=\"0 0 48 48\"><path d=\"M7 6.5h34L37 27H3z\" fill=\"currentColor\" fill-opacity=\".16\"/><path d=\"M7 6.5h34L37 27H3zM15.6 6.5L13 27M24.2 6.5L23 27M32.8 6.5L33 27M5.6 13.3h34M4.3 20.1h34.4M15 27l-3.5 13M33 27l3.5 13M8 40h32M20 27v8.5M28 27v8.5\"/></symbol><symbol id=\"i-ruler\" viewBox=\"0 0 48 48\"><path d=\"M5 32.5L32.5 5 43 15.5 15.5 43z\" fill=\"currentColor\" fill-opacity=\".16\"/><path d=\"M5 32.5L32.5 5 43 15.5 15.5 43zM12 25.5l4 4M17 20.5l2.8 2.8M22 15.5l4 4M27 10.5l2.8 2.8\"/></symbol></svg><div id=\"conteudo\" class=\"b-main\">\n    <!-- A linha de energia que desce: nasce na secção 02, acende o nó de cada secção e termina no botão final (final.js) -->\n    <svg class=\"f-circuit\" data-circuit aria-hidden=\"true\" focusable=\"false\"></svg>\n\n    <section class=\"hero\" aria-labelledby=\"hero-title\" data-hero>\n      <div class=\"hero__copy\">\n        <h1 class=\"hero__title\" id=\"hero-title\">\n          <span class=\"line\"><span class=\"kern-a\">Energia</span> para a <span class=\"kern-s\">sua</span></span>\n          <span class=\"line\">casa, <span class=\"kern-m\">medida</span> ao</span>\n          <span class=\"line\">detalhe.</span>\n          <img class=\"hero__type-m\" src=\"__ASSETS__/img/hero-type-title.svg\" alt=\"\" width=\"1025\" height=\"327\">\n        </h1>\n        <!-- Letras do mockup aprovado em vetor (desktop). O h1 e o \"30 anos\" continuam como texto real, para SEO e leitores de ecrã. -->\n        <img class=\"hero__type\" src=\"__ASSETS__/img/hero-type.svg\" alt=\"\" width=\"1252\" height=\"345\">\n        <p class=\"proof\">\n          <span class=\"proof__rule\" aria-hidden=\"true\"></span>\n          <img class=\"proof__type-m\" src=\"__ASSETS__/img/hero-type-proof.svg\" alt=\"\" width=\"257\" height=\"100\">\n          <span class=\"proof__num\"><span class=\"kern-30\">30</span> <span class=\"kern-anos\">anos</span></span>\n          <span class=\"proof__label\">de experiência</span>\n        </p>\n      </div>\n\n      <form class=\"sim\" id=\"simulador\" action=\"#simulador\" novalidate data-sticky-stop aria-labelledby=\"sim-title\">\n        <h2 class=\"sim__title\" id=\"sim-title\">Simulador de poupança</h2>\n\n        <div class=\"sim__field\">\n          <label class=\"sim__label\" for=\"fatura\">Valor médio mensal da fatura de eletricidade (€)</label>\n          <input class=\"sim__input\" id=\"fatura\" name=\"fatura\" type=\"text\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Ex.: 120\" aria-describedby=\"fatura-erro\" required>\n          <p class=\"sim__error\" id=\"fatura-erro\" role=\"alert\" hidden></p>\n        </div>\n\n        <fieldset class=\"segmented\">\n          <legend class=\"visually-hidden\">Tipo de cliente</legend>\n          <label class=\"segmented__opt\">\n            <input type=\"radio\" name=\"tipo\" value=\"casa\" checked>\n            <span><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-home\"/></svg>Casa</span>\n          </label>\n          <label class=\"segmented__opt\">\n            <input type=\"radio\" name=\"tipo\" value=\"empresa\">\n            <span><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-building\"/></svg>Empresa</span>\n          </label>\n        </fieldset>\n\n        <div class=\"sim__actions\">\n          <button class=\"btn btn--lime sim__cta\" type=\"submit\">\n            <svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg>\n            <span>Simular a minha poupança</span>\n          </button>\n          <span class=\"sim__rule\" aria-hidden=\"true\"></span>\n          <a class=\"sim__store\" href=\"#loja\">Ir para a loja <svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg></a>\n        </div>\n\n        <p class=\"sim__status\" role=\"status\" aria-live=\"polite\"></p>\n      </form>\n\n      <figure class=\"hero__visual\" data-energy>\n        <picture>\n          <source type=\"image/webp\" srcset=\"__ASSETS__/img/hero-plate-1200.webp 1200w, __ASSETS__/img/hero-plate-1920.webp 1920w, __ASSETS__/img/hero-plate-2880.webp 2880w\" sizes=\"(min-width: 1100px) 57vw, 100vw\">\n          <img class=\"hero__img\" src=\"__ASSETS__/img/hero-plate-1920.webp\" width=\"3840\" height=\"2010\" fetchpriority=\"high\"\n               alt=\"Representação conceptual de uma casa em corte, com painéis solares no telhado, inversor e bateria na parede exterior e um carro elétrico a carregar no telheiro.\">\n        </picture>\n\n        <canvas class=\"energy\" aria-hidden=\"true\"></canvas>\n\n        <span class=\"node\" data-node=\"modulos\"></span>\n        <span class=\"node\" data-node=\"inversor\"></span>\n        <span class=\"node\" data-node=\"bateria\"></span>\n\n        <a class=\"callout\" href=\"#cat-modulos\" data-callout=\"modulos\" style=\"--x:56.7%; --y:6.25%\">Módulos fotovoltaicos</a>\n        <a class=\"callout\" href=\"#cat-inversores\" data-callout=\"inversor\" style=\"--x:66.9%; --y:45.4%\">Inversor</a>\n        <a class=\"callout\" href=\"#cat-baterias\" data-callout=\"bateria\" style=\"--x:66.9%; --y:71.1%\">Bateria</a>\n      </figure>\n    </section>\n\n    <section class=\"paths\" aria-label=\"Como podemos ajudar\">\n      <article class=\"path path--install\" id=\"instalar\" aria-labelledby=\"install-title\">\n        <div class=\"path__main\">\n          <p class=\"path__tag\">Soluções completas</p>\n          <h2 class=\"path__title\" id=\"install-title\">Quero instalar uma solução</h2>\n          <p class=\"path__body\">Do primeiro cálculo à instalação, tratamos de tudo para a sua casa ou empresa.</p>\n        </div>\n        <div class=\"path__side\">\n          <ol class=\"steps\">\n            <li class=\"step\">\n              <span class=\"step__ring\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-calc\"/></svg></span>\n              <span class=\"step__name\">Simulador</span>\n              <span class=\"step__note\">Calcule a sua poupança</span>\n            </li>\n            <li class=\"step\">\n              <span class=\"step__ring\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-ruler\"/></svg></span>\n              <span class=\"step__name\">Dimensionamento</span>\n              <span class=\"step__note\">Solução à medida da sua necessidade</span>\n            </li>\n            <li class=\"step\">\n              <span class=\"step__ring\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-hardhat\"/></svg></span>\n              <span class=\"step__name\">Instalação</span>\n              <span class=\"step__note\">Planeamento e execução</span>\n            </li>\n          </ol>\n          <!-- Página atual de pedido de orçamento; no Wix passa a ser o formulário \"Pedir dimensionamento\". -->\n          <a class=\"btn btn--lime path__cta\" href=\"#dimensionamento\">\n            <svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg>\n            <span>Quero começar</span>\n          </a>\n        </div>\n        <img class=\"path__leaf\" src=\"__ASSETS__/img/simbolo-technogreen-640.webp\" alt=\"\" width=\"1254\" height=\"1254\">\n      </article>\n\n      <article class=\"path path--store\" id=\"loja-rapida\" aria-labelledby=\"store-title\">\n        <p class=\"path__tag\">Equipamentos</p>\n        <h2 class=\"path__title\" id=\"store-title\">Quero comprar equipamentos</h2>\n        <p class=\"path__body\">Equipamentos de energia para a sua casa ou empresa, num só lugar.</p>\n        <!-- Categorias reais da loja atual; no Wix ligam às categorias do Wix Stores. -->\n        <ul class=\"cats\">\n          <li><a class=\"cat\" id=\"cat-kits\" href=\"https://www.technogreen.pt/kits-autoconsumo\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-kit\"/></svg><span>Kits</span><svg class=\"icon icon--chev\" aria-hidden=\"true\"><use href=\"#i-chevron\"/></svg></a></li>\n          <li><a class=\"cat\" id=\"cat-inversores\" href=\"https://www.technogreen.pt/inversoresongrid\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-inverter\"/></svg><span>Inversores</span><svg class=\"icon icon--chev\" aria-hidden=\"true\"><use href=\"#i-chevron\"/></svg></a></li>\n          <li><a class=\"cat\" id=\"cat-baterias\" href=\"https://www.technogreen.pt/bateriassolares\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-battery\"/></svg><span>Baterias solares</span><svg class=\"icon icon--chev\" aria-hidden=\"true\"><use href=\"#i-chevron\"/></svg></a></li>\n          <li><a class=\"cat\" id=\"cat-modulos\" href=\"https://www.technogreen.pt/moduloseestruturas\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-module\"/></svg><span>Módulos e estruturas</span><svg class=\"icon icon--chev\" aria-hidden=\"true\"><use href=\"#i-chevron\"/></svg></a></li>\n          <li><a class=\"cat\" id=\"cat-ev\" href=\"https://www.technogreen.pt/carregadoresev\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-ev\"/></svg><span>Carregadores EV</span><svg class=\"icon icon--chev\" aria-hidden=\"true\"><use href=\"#i-chevron\"/></svg></a></li>\n          <li><a class=\"cat\" id=\"cat-bombas\" href=\"https://www.technogreen.pt/bombas-de-calor\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-heatpump\"/></svg><span>Bombas de calor</span><svg class=\"icon icon--chev\" aria-hidden=\"true\"><use href=\"#i-chevron\"/></svg></a></li>\n        </ul>\n      </article>\n    </section>\n\n    <!-- Soluções TechnoGreen: o que a TechnoGreen dimensiona e instala, apresentado como sistema (não como catálogo). -->\n    <section class=\"solutions f-sol\" id=\"solucoes\" aria-labelledby=\"solutions-title\" data-station=\"01\" data-label=\"Soluções\">\n      <p class=\"solutions__eyebrow\"><span class=\"f-lamp\" data-lamp aria-hidden=\"true\"><svg class=\"f-lamp__bulb\" viewBox=\"0 0 40 47\" width=\"40\" height=\"47\" focusable=\"false\"><defs><radialGradient id=\"f-lamp-core\" cx=\"50%\" cy=\"50%\" r=\"50%\"><stop offset=\"0\" stop-color=\"#e6f77a\" stop-opacity=\"0.95\"/><stop offset=\"0.55\" stop-color=\"#e6f77a\" stop-opacity=\"0.35\"/><stop offset=\"1\" stop-color=\"#e6f77a\" stop-opacity=\"0\"/></radialGradient></defs><path class=\"f-lamp__glass\" d=\"M14.2 33.5C14.2 28.5 5 25.5 5 17a15 15 0 1 1 30 0c0 8.5-9.2 11.5-9.2 16.5z\"/><circle class=\"f-lamp__core\" cx=\"20\" cy=\"17\" r=\"13\" fill=\"url(#f-lamp-core)\"/><path class=\"f-lamp__rim\" d=\"M14.2 33.5C14.2 28.5 5 25.5 5 17a15 15 0 1 1 30 0c0 8.5-9.2 11.5-9.2 16.5z\"/><g class=\"f-lamp__base\"><rect x=\"14.2\" y=\"35\" width=\"11.6\" height=\"2.6\" rx=\"1.3\"/><rect x=\"14.8\" y=\"38.8\" width=\"10.4\" height=\"2.6\" rx=\"1.3\"/><path d=\"M16.6 42.6h6.8l-1.5 3.4h-3.8z\"/></g></svg><img class=\"f-lamp__leaf\" src=\"__ASSETS__/img/simbolo-technogreen-640.webp\" alt=\"\" width=\"1254\" height=\"1254\" decoding=\"async\"></span><b>01</b><span>Soluções TechnoGreen</span><span class=\"solutions__eyebrow-sep\" aria-hidden=\"true\"></span><span>Casa · Empresa</span></p>\n      <div class=\"solutions__head\">\n        <h2 class=\"solutions__title\" id=\"solutions-title\">Energia que trabalha<br>em conjunto.</h2>\n        <p class=\"solutions__lead\">Da produção ao consumo, dimensionamos e instalamos soluções de energia para casas e empresas.</p>\n      </div>\n      <ol class=\"solutions__flow\">\n          <li class=\"solutions__step\">\n            <p class=\"solutions__ref\"><b>01</b> · Produção</p>\n            <h3 class=\"solutions__verb\">Produzir</h3>\n            <span class=\"solutions__node\" aria-hidden=\"true\"></span>\n            <span class=\"solutions__drop\" aria-hidden=\"true\"></span>\n            <span class=\"solutions__arrow\" aria-hidden=\"true\"></span>\n            <div class=\"solutions__body\">\n              <p class=\"solutions__name\">Energia solar fotovoltaica</p>\n              <p class=\"solutions__desc\">Painéis solares e inversor, dimensionados para o seu consumo.</p>\n            </div>\n          </li>\n          <li class=\"solutions__step\">\n            <p class=\"solutions__ref\"><b>02</b> · Reserva</p>\n            <h3 class=\"solutions__verb\">Armazenar</h3>\n            <span class=\"solutions__node\" aria-hidden=\"true\"></span>\n            <span class=\"solutions__drop\" aria-hidden=\"true\"></span>\n            <span class=\"solutions__arrow\" aria-hidden=\"true\"></span>\n            <div class=\"solutions__body\">\n              <p class=\"solutions__name\">Baterias e sistemas anti-apagão</p>\n              <p class=\"solutions__desc\">Baterias para guardar a energia produzida. Sistemas anti-apagão para quando a rede falha.</p>\n            </div>\n          </li>\n          <li class=\"solutions__step\">\n            <p class=\"solutions__ref\"><b>03</b> · Mobilidade</p>\n            <h3 class=\"solutions__verb\">Carregar</h3>\n            <span class=\"solutions__node\" aria-hidden=\"true\"></span>\n            <span class=\"solutions__drop\" aria-hidden=\"true\"></span>\n            <span class=\"solutions__arrow\" aria-hidden=\"true\"></span>\n            <div class=\"solutions__body\">\n              <p class=\"solutions__name\">Veículos elétricos</p>\n              <p class=\"solutions__desc\">Carregadores para veículos elétricos em casa ou na empresa.</p>\n            </div>\n          </li>\n          <li class=\"solutions__step\">\n            <p class=\"solutions__ref\"><b>04</b> · Conforto</p>\n            <h3 class=\"solutions__verb\">Climatizar</h3>\n            <span class=\"solutions__node\" aria-hidden=\"true\"></span>\n            <span class=\"solutions__drop\" aria-hidden=\"true\"></span>\n            <div class=\"solutions__body\">\n              <p class=\"solutions__name\">Bombas de calor e ar condicionado</p>\n              <p class=\"solutions__desc\">Aquecimento e arrefecimento para casas e espaços de trabalho.</p>\n            </div>\n          </li>\n      </ol>\n      <div class=\"solutions__foot\">\n        <p class=\"solutions__more\"><b>Também:</b> instalações técnicas e assistência técnica.</p>\n        <div class=\"solutions__actions\">\n          <a class=\"solutions__link\" href=\"#contactos\">Falar com a equipa <svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg></a>\n          <a class=\"btn btn--lime solutions__cta\" href=\"#dimensionamento\">\n            <svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg>\n            <span>Pedir dimensionamento</span>\n          </a>\n        </div>\n      </div>\n    </section>\n\n    <!-- 02 · Dimensionamento: a ficha do seu pedido (contactos só no passo 2, \"Enviar pedido\" junto aos campos) -->\n    <section class=\"b-sec b-sec--mist b3\" id=\"dimensionamento\" aria-labelledby=\"b3-title\" data-step=\"1\" data-station=\"02\" data-label=\"Dimensionamento\">\n      <div class=\"b-in\">\n        <p class=\"b-eb\"><b>02</b><span>Dimensionamento</span></p>\n        <form class=\"b3__grid\" id=\"b3-form\" action=\"#dimensionamento\" novalidate aria-labelledby=\"b3-title\">\n          <div class=\"b3__main\">\n            <div class=\"b3__intro\">\n              <h2 class=\"b-h2\" id=\"b3-title\">Descubra a solução de energia ideal para si.</h2>\n              <p class=\"b-lead\">Diga-nos como utiliza a energia e ajudamos a encontrar o sistema mais adequado para a sua casa ou empresa.</p>\n            </div>\n            <div class=\"b3__step\" data-step1>\n              <div class=\"b3__qs\">\n                <fieldset class=\"b3__q\" data-q=\"local\">\n                  <span class=\"b3__qnode\" aria-hidden=\"true\"></span>\n                  <legend class=\"b3__legend\">Onde pretende instalar?</legend>\n                  <div class=\"b3__opts b3__opts--tiles\">\n                    <label class=\"b3__opt\"><input type=\"radio\" name=\"local\" value=\"casa\" aria-describedby=\"b3-local-erro\"><span><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-home\"/></svg>Na minha casa</span></label>\n                    <label class=\"b3__opt\"><input type=\"radio\" name=\"local\" value=\"empresa\" aria-describedby=\"b3-local-erro\"><span><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-building\"/></svg>Na minha empresa</span></label>\n                  </div>\n                  <p class=\"b3__err\" id=\"b3-local-erro\" hidden></p>\n                </fieldset>\n                <fieldset class=\"b3__q\" data-q=\"fatura\">\n                  <span class=\"b3__qnode\" aria-hidden=\"true\"></span>\n                  <legend class=\"b3__legend\">Quanto paga de eletricidade por mês?</legend>\n                  <div class=\"b3__opts b3__opts--4\">\n                    <label class=\"b3__opt\"><input type=\"radio\" name=\"fatura\" value=\"ate-100\"><span>Até 100&nbsp;€</span></label>\n                    <label class=\"b3__opt\"><input type=\"radio\" name=\"fatura\" value=\"100-200\"><span>100&nbsp;€ a 200&nbsp;€</span></label>\n                    <label class=\"b3__opt\"><input type=\"radio\" name=\"fatura\" value=\"mais-200\"><span>Mais de 200&nbsp;€</span></label>\n                    <label class=\"b3__opt\"><input type=\"radio\" name=\"fatura\" value=\"nao-sei\"><span>Não sei</span></label>\n                  </div>\n                </fieldset>\n                <fieldset class=\"b3__q\" data-q=\"armazenar\">\n                  <span class=\"b3__qnode\" aria-hidden=\"true\"></span>\n                  <legend class=\"b3__legend\">Gostaria de armazenar energia para utilizar à noite?</legend>\n                  <div class=\"b3__opts b3__opts--3\">\n                    <label class=\"b3__opt\"><input type=\"radio\" name=\"armazenar\" value=\"sim\"><span>Sim</span></label>\n                    <label class=\"b3__opt\"><input type=\"radio\" name=\"armazenar\" value=\"nao\"><span>Não</span></label>\n                    <label class=\"b3__opt b3__opt--wide\"><input type=\"radio\" name=\"armazenar\" value=\"aconselhamento\"><span>Preciso de aconselhamento</span></label>\n                  </div>\n                </fieldset>\n              </div>\n            </div>\n            <div class=\"b3__step\" data-step2 hidden>\n              <button class=\"b3__back\" type=\"button\" data-back><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg><span>Voltar às perguntas</span></button>\n              <h3 class=\"b3__s2title\" tabindex=\"-1\" data-s2title>Os seus contactos</h3>\n              <p class=\"b3__s2lead\">Com estes dados, a equipa TechnoGreen prepara o dimensionamento e entra em contacto consigo.</p>\n              <p class=\"b3__req\">Todos os campos são obrigatórios.</p>\n              <div class=\"b3__fields\">\n                <div class=\"b3__fld\"><label for=\"b3-nome\">Nome</label><input id=\"b3-nome\" name=\"nome\" type=\"text\" autocomplete=\"name\" required aria-required=\"true\" aria-describedby=\"b3-nome-erro\"><p class=\"b3__err\" id=\"b3-nome-erro\" hidden></p></div>\n                <div class=\"b3__fld\"><label for=\"b3-email\">Email</label><input id=\"b3-email\" name=\"email\" type=\"email\" autocomplete=\"email\" inputmode=\"email\" spellcheck=\"false\" required aria-required=\"true\" aria-describedby=\"b3-email-erro\"><p class=\"b3__err\" id=\"b3-email-erro\" hidden></p></div>\n                <div class=\"b3__fld\"><label for=\"b3-telefone\">Telefone</label><input id=\"b3-telefone\" name=\"telefone\" type=\"tel\" autocomplete=\"tel\" inputmode=\"tel\" required aria-required=\"true\" aria-describedby=\"b3-telefone-erro\"><p class=\"b3__err\" id=\"b3-telefone-erro\" hidden></p></div>\n                <div class=\"b3__fld\"><label for=\"b3-localidade\">Código postal ou localidade</label><input id=\"b3-localidade\" name=\"localidade\" type=\"text\" autocomplete=\"off\" required aria-required=\"true\" aria-describedby=\"b3-localidade-erro\"><p class=\"b3__err\" id=\"b3-localidade-erro\" hidden></p></div>\n              </div>\n              <div class=\"b3__consent\">\n                <label class=\"b3__check\"><input type=\"checkbox\" id=\"b3-consentimento\" name=\"consentimento\" required aria-required=\"true\" aria-describedby=\"b3-consentimento-erro b3-rgpd\"><span>Aceito que a TechnoGreen utilize estes dados para responder ao meu pedido.</span></label>\n                <p class=\"b3__hint\" id=\"b3-rgpd\">Texto de privacidade (RGPD) a fornecer e validar pela TechnoGreen.</p>\n                <p class=\"b3__err\" id=\"b3-consentimento-erro\" hidden></p>\n              </div>\n              <!-- O envio fica junto aos campos de contacto -->\n              <div class=\"b3__send\">\n                <button class=\"btn btn--lime b3__cta\" type=\"submit\" data-send><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg><span>Enviar pedido</span></button>\n                <p class=\"b3__status\" role=\"status\" aria-live=\"polite\"></p>\n              </div>\n            </div>\n          </div>\n\n          <aside class=\"b3__sheet\" aria-labelledby=\"b3-sheet-t\" data-sheet>\n            <div class=\"b3__head\">\n              <p class=\"b3__meta\"><span data-sheet-step aria-live=\"polite\">Passo 1 de 2</span><span data-sheet-date></span></p>\n              <div class=\"b3__headrow\">\n                <h3 class=\"b3__sheet-t\" id=\"b3-sheet-t\">A ficha do seu pedido</h3>\n                <button class=\"b3__edit\" type=\"button\" data-edit hidden>Editar respostas</button>\n              </div>\n            </div>\n            <ol class=\"b3__rows\">\n              <li class=\"b3__row\" data-row=\"local\"><span class=\"b3__node\" aria-hidden=\"true\"></span><span class=\"b3__k\">Local</span><span class=\"b3__v\" data-val=\"local\">Por indicar</span></li>\n              <li class=\"b3__row\" data-row=\"fatura\"><span class=\"b3__node\" aria-hidden=\"true\"></span><span class=\"b3__k\">Fatura mensal</span><span class=\"b3__v\" data-val=\"fatura\">Por indicar</span></li>\n              <li class=\"b3__row\" data-row=\"armazenar\"><span class=\"b3__node\" aria-hidden=\"true\"></span><span class=\"b3__k\">Armazenamento</span><span class=\"b3__v\" data-val=\"armazenar\">Por indicar</span></li>\n              <li class=\"b3__row\" data-row=\"contacto\"><span class=\"b3__node\" aria-hidden=\"true\"></span><span class=\"b3__k\">Contacto</span><span class=\"b3__v\" data-val=\"contacto\">No passo 2</span></li>\n            </ol>\n            <div class=\"b3__foot\" data-foot1>\n              <button class=\"btn btn--lime b3__cta\" type=\"submit\" data-next><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg><span>Continuar para contactos</span></button>\n              <p class=\"b3__note\"><b>Não precisa de saber que equipamento escolher.</b> A equipa TechnoGreen analisa as suas respostas e faz o dimensionamento para o seu caso.</p>\n            </div>\n            <p class=\"b3__note b3__note--s2\" data-foot2 hidden>Confirme os dados e envie o pedido com os seus contactos.</p>\n          </aside>\n        </form>\n      </div>\n    </section>\n\n    <!-- 03 · Anti-apagão (versão C): a casa à noite; na falha de rede, a bateria mantém os circuitos escolhidos -->\n    <section class=\"c-night c4\" id=\"anti-apagao\" aria-labelledby=\"c4-title\" data-grid=\"on\" data-station=\"03\" data-label=\"Anti-apagão\">\n      <div class=\"c4__media\" aria-hidden=\"true\">\n        <img class=\"c4__img\" src=\"__ASSETS__/img/hero-plate-1920.webp\" width=\"1920\" height=\"1005\" alt=\"\" loading=\"lazy\">\n        <span class=\"c4__glow c4__glow--bat\"></span>\n        <span class=\"c4__glow c4__glow--sala\"></span>\n        <span class=\"c4__glow c4__glow--quarto\"></span>\n      </div>\n      <div class=\"b-in c4__in\">\n        <p class=\"b-eb b-eb--on-forest\"><b>03</b><span>Anti-apagão</span></p>\n        <h2 class=\"b-h2\" id=\"c4-title\">Não fique no escuro quando a energia falhar.</h2>\n        <ul class=\"c4__list\">\n          <li>Energia de reserva quando a rede falha</li>\n          <li>Energia contínua para a sua casa ou empresa</li>\n          <li>Menos dependência da rede elétrica</li>\n        </ul>\n        <fieldset class=\"c4__switch\">\n          <legend>Experimente</legend>\n          <label><input type=\"radio\" name=\"c4-rede\" value=\"on\" checked><span>Rede ligada</span></label>\n          <label><input type=\"radio\" name=\"c4-rede\" value=\"off\"><span>Falha de rede</span></label>\n        </fieldset>\n        <p class=\"c4__cap\" data-grid-cap aria-live=\"polite\">À noite, com a rede ligada, a casa usa a energia da rede e, se tiver bateria, a energia guardada durante o dia.</p>\n        <p class=\"c4__note\">Disponível nos sistemas anti-apagão e Backup-Full.</p>\n        <div class=\"c4__acts\">\n          <a class=\"btn btn--lime b-cta\" href=\"https://www.technogreen.pt/\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg><span>Ver kits anti-apagão</span></a>\n          <a class=\"b-link b-link--on-forest\" href=\"#dimensionamento\">Pedir dimensionamento <svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg></a>\n        </div>\n      </div>\n    </section>\n\n    <!-- 04 · Loja: catálogo técnico por separadores (produtos e preços vêm da Wix Store) -->\n    <section class=\"b-sec b5\" id=\"loja\" aria-labelledby=\"b5-title\" data-station=\"04\" data-label=\"Loja online\">\n      <div class=\"b-in\">\n        <p class=\"b-eb\"><b>04</b><span>Loja online</span></p>\n        <div class=\"b5__head\">\n          <h2 class=\"b-h2\" id=\"b5-title\">Equipamentos de energia, num só lugar.</h2>\n          <p class=\"b-lead\">Módulos, inversores, baterias, carregadores e climatização, com a informação técnica de cada produto.</p>\n        </div>\n        <div class=\"b5__tabs\" role=\"tablist\" aria-label=\"Categorias da loja\">\n          <button role=\"tab\" id=\"t-kits\" aria-controls=\"p-kits\" aria-selected=\"true\" tabindex=\"0\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-kit\"/></svg>Kits solares</button>\n          <button role=\"tab\" id=\"t-mod\" aria-controls=\"p-mod\" aria-selected=\"false\" tabindex=\"-1\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-module\"/></svg>Módulos e estruturas</button>\n          <button role=\"tab\" id=\"t-inv\" aria-controls=\"p-inv\" aria-selected=\"false\" tabindex=\"-1\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-inverter\"/></svg>Inversores</button>\n          <button role=\"tab\" id=\"t-bat\" aria-controls=\"p-bat\" aria-selected=\"false\" tabindex=\"-1\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-battery\"/></svg>Baterias solares</button>\n          <button role=\"tab\" id=\"t-ev\" aria-controls=\"p-ev\" aria-selected=\"false\" tabindex=\"-1\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-ev\"/></svg>Carregadores EV</button>\n        </div>\n        <div class=\"b5__panels\">\n          <div class=\"b5__panel\" role=\"tabpanel\" id=\"p-kits\" aria-labelledby=\"t-kits\" tabindex=\"0\">\n            <div class=\"b5__spec\"><p class=\"b5__k\">Gamas</p><ul class=\"b5__subs\"><li><a href=\"https://www.technogreen.pt/kits-autoconsumo\">Residencial</a></li><li><a href=\"https://www.technogreen.pt/kit-autoconsumo-empresarial\">Empresarial</a></li><li><a href=\"https://www.technogreen.pt/\">Anti-apagão</a></li></ul><a class=\"b-link\" href=\"https://www.technogreen.pt/kits-autoconsumo\">Ver kits na loja <svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg></a></div>\n            <ul class=\"b5__prods\"><li class=\"b5__prod\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-kit\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li><li class=\"b5__prod b5__prod--m\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-kit\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li><li class=\"b5__prod\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-kit\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li><li class=\"b5__prod\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-kit\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li></ul>\n          </div>\n          <div class=\"b5__panel\" role=\"tabpanel\" id=\"p-mod\" aria-labelledby=\"t-mod\" tabindex=\"0\" hidden>\n            <div class=\"b5__spec\"><p class=\"b5__k\">Gama</p><ul class=\"b5__subs\"><li><a href=\"https://www.technogreen.pt/moduloseestruturas\">Módulos e estruturas</a></li></ul><a class=\"b-link\" href=\"https://www.technogreen.pt/moduloseestruturas\">Ver módulos na loja <svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg></a></div>\n            <ul class=\"b5__prods\"><li class=\"b5__prod\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-module\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li><li class=\"b5__prod b5__prod--m\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-module\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li><li class=\"b5__prod\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-module\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li><li class=\"b5__prod\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-module\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li></ul>\n          </div>\n          <div class=\"b5__panel\" role=\"tabpanel\" id=\"p-inv\" aria-labelledby=\"t-inv\" tabindex=\"0\" hidden>\n            <div class=\"b5__spec\"><p class=\"b5__k\">Gamas</p><ul class=\"b5__subs\"><li><a href=\"https://www.technogreen.pt/inversoresongrid\">On grid</a></li><li><a href=\"https://www.technogreen.pt/inversoresongiroffgrid\">Off/on grid</a></li><li><a href=\"https://www.technogreen.pt/inversoresoffgrid\">Off grid</a></li></ul><a class=\"b-link\" href=\"https://www.technogreen.pt/inversoresongrid\">Ver inversores na loja <svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg></a></div>\n            <ul class=\"b5__prods\"><li class=\"b5__prod\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-inverter\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li><li class=\"b5__prod b5__prod--m\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-inverter\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li><li class=\"b5__prod\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-inverter\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li><li class=\"b5__prod\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-inverter\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li></ul>\n          </div>\n          <div class=\"b5__panel\" role=\"tabpanel\" id=\"p-bat\" aria-labelledby=\"t-bat\" tabindex=\"0\" hidden>\n            <div class=\"b5__spec\"><p class=\"b5__k\">Gama</p><ul class=\"b5__subs\"><li><a href=\"https://www.technogreen.pt/bateriassolares\">Baterias solares</a></li></ul><a class=\"b-link\" href=\"https://www.technogreen.pt/bateriassolares\">Ver baterias na loja <svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg></a></div>\n            <ul class=\"b5__prods\"><li class=\"b5__prod\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-battery\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li><li class=\"b5__prod b5__prod--m\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-battery\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li><li class=\"b5__prod\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-battery\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li><li class=\"b5__prod\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-battery\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li></ul>\n          </div>\n          <div class=\"b5__panel\" role=\"tabpanel\" id=\"p-ev\" aria-labelledby=\"t-ev\" tabindex=\"0\" hidden>\n            <div class=\"b5__spec\"><p class=\"b5__k\">Gama</p><ul class=\"b5__subs\"><li><a href=\"https://www.technogreen.pt/carregadoresev\">Carregadores EV</a></li></ul><a class=\"b-link\" href=\"https://www.technogreen.pt/carregadoresev\">Ver carregadores na loja <svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg></a></div>\n            <ul class=\"b5__prods\"><li class=\"b5__prod\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-ev\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li><li class=\"b5__prod b5__prod--m\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-ev\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li><li class=\"b5__prod\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-ev\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li><li class=\"b5__prod\"><span class=\"b5__ph\"><svg class=\"icon\"><use href=\"#i-ev\"/></svg></span><p class=\"b5__pname\">Produto da Wix Store</p><p class=\"b5__pmeta\">Imagem, nome e preço vêm da loja</p></li></ul>\n          </div>\n        </div>\n        <div class=\"b5__foot\">\n          <p class=\"b-note\">Consulte preços e disponibilidade na loja online.</p>\n          <a class=\"btn btn--lime b-cta\" href=\"https://www.technogreen.pt/moduloseestruturas\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg><span>Ir para a loja</span></a>\n        </div>\n      </div>\n    </section>\n\n    <!-- 05 · Climatização: um ramo do circuito -->\n    <section class=\"b-sec b-sec--mist b6\" id=\"climatizacao\" aria-labelledby=\"b6-title\" data-station=\"05\" data-label=\"Climatização\">\n      <div class=\"b-in\">\n        <p class=\"b-eb\"><b>05</b><span>Climatização</span></p>\n        <div class=\"b6__grid\">\n          <h2 class=\"b-h2 b-h2--s\" id=\"b6-title\">Conforto em casa e no trabalho.</h2>\n          <div class=\"b6__branch\">\n            <a class=\"b6__item\" href=\"https://www.technogreen.pt/bombas-de-calor\"><span class=\"b6__node\" aria-hidden=\"true\"></span><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-heatpump\"/></svg><span class=\"b6__name\">Bombas de calor</span><span class=\"b6__go\">Ver na loja</span></a>\n            <a class=\"b6__item\" href=\"https://www.technogreen.pt/ar-condicionado\"><span class=\"b6__node\" aria-hidden=\"true\"></span><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#x-ac\"/></svg><span class=\"b6__name\">Ar condicionado</span><span class=\"b6__go\">Ver na loja</span></a>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- 06 · Assistência técnica: só pedidos de assistência. O formulário fica escondido até ao clique em \"Pedir assistência técnica\";\n         dois passos (equipamento, contactos), estado próprio, separado do dimensionamento. Sem envio real (Wix Forms, a definir). -->\n    <section class=\"b-sec f7\" id=\"assistencia\" aria-labelledby=\"f7-title\" data-view=\"intro\" data-station=\"06\" data-label=\"Assistência técnica\">\n      <div class=\"b-in\">\n        <p class=\"b-eb\"><b>06</b><span>Assistência técnica</span></p>\n        <div class=\"f7__grid\">\n          <div class=\"f7__main\">\n            <h2 class=\"b-h2\" id=\"f7-title\">Precisa de assistência técnica?</h2>\n            <div class=\"f7__intro\" data-f7-intro>\n              <p class=\"b-lead\">Tem um equipamento com problemas ou precisa de apoio técnico? Envie-nos o seu pedido e a equipa TechnoGreen entra em contacto consigo.</p>\n              <div class=\"b-acts f7__acts\">\n                <button class=\"btn btn--lime b-cta\" type=\"button\" data-f7-open aria-controls=\"f7-form\" aria-expanded=\"false\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg><span>Pedir assistência técnica</span></button>\n              </div>\n              <p class=\"f7__aside\">Para uma nova instalação, faça antes o <a href=\"#dimensionamento\">pedido de dimensionamento</a>.</p>\n            </div>\n            <form class=\"f7__form\" id=\"f7-form\" novalidate aria-labelledby=\"f7-form-t\" hidden>\n              <div class=\"f7__step\" data-f7-s1>\n                <button class=\"b3__back\" type=\"button\" data-f7-close><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg><span>Voltar</span></button>\n                <p class=\"f7__meta\">Passo 1 de 2</p>\n                <h3 class=\"b3__s2title\" id=\"f7-form-t\" tabindex=\"-1\" data-f7-t1>O equipamento</h3>\n                <p class=\"b3__req\">Os campos marcados com * são obrigatórios.</p>\n                <div class=\"b3__fields\">\n                  <div class=\"b3__fld\"><label for=\"f7-tipo\">Tipo de equipamento *</label><select id=\"f7-tipo\" name=\"tipo\" required aria-required=\"true\" aria-describedby=\"f7-tipo-erro\"><option value=\"\">Escolha uma opção</option><option value=\"paineis\">Painéis solares</option><option value=\"inversor\">Inversor</option><option value=\"bateria\">Bateria</option><option value=\"carregador\">Carregador EV</option><option value=\"bomba\">Bomba de calor</option><option value=\"ar\">Ar condicionado</option><option value=\"outro\">Outro</option></select><p class=\"b3__err\" id=\"f7-tipo-erro\" hidden></p></div>\n                  <div class=\"b3__fld\"><label for=\"f7-marca\">Marca e modelo <span class=\"f7__opt\">(opcional)</span></label><input id=\"f7-marca\" name=\"marca\" type=\"text\" autocomplete=\"off\"></div>\n                  <div class=\"b3__fld f7__wide\"><label for=\"f7-descricao\">Descrição do problema *</label><textarea id=\"f7-descricao\" name=\"descricao\" rows=\"4\" required aria-required=\"true\" aria-describedby=\"f7-descricao-dica f7-descricao-erro\"></textarea><p class=\"f7__tip\" id=\"f7-descricao-dica\">O que está a acontecer e desde quando.</p><p class=\"b3__err\" id=\"f7-descricao-erro\" hidden></p></div>\n                </div>\n                <div class=\"b3__send\">\n                  <button class=\"btn btn--lime b3__cta\" type=\"submit\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg><span>Continuar para contactos</span></button>\n                </div>\n              </div>\n              <div class=\"f7__step\" data-f7-s2 hidden>\n                <button class=\"b3__back\" type=\"button\" data-f7-prev><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg><span>Voltar ao equipamento</span></button>\n                <p class=\"f7__meta\">Passo 2 de 2</p>\n                <h3 class=\"b3__s2title\" tabindex=\"-1\" data-f7-t2>Os seus contactos</h3>\n                <p class=\"b3__req\">Todos os campos são obrigatórios.</p>\n                <div class=\"b3__fields\">\n                  <div class=\"b3__fld\"><label for=\"f7-nome\">Nome</label><input id=\"f7-nome\" name=\"nome\" type=\"text\" autocomplete=\"name\" required aria-required=\"true\" aria-describedby=\"f7-nome-erro\"><p class=\"b3__err\" id=\"f7-nome-erro\" hidden></p></div>\n                  <div class=\"b3__fld\"><label for=\"f7-telefone\">Telefone</label><input id=\"f7-telefone\" name=\"telefone\" type=\"tel\" autocomplete=\"tel\" inputmode=\"tel\" required aria-required=\"true\" aria-describedby=\"f7-telefone-erro\"><p class=\"b3__err\" id=\"f7-telefone-erro\" hidden></p></div>\n                  <div class=\"b3__fld\"><label for=\"f7-email\">Email</label><input id=\"f7-email\" name=\"email\" type=\"email\" autocomplete=\"email\" inputmode=\"email\" spellcheck=\"false\" required aria-required=\"true\" aria-describedby=\"f7-email-erro\"><p class=\"b3__err\" id=\"f7-email-erro\" hidden></p></div>\n                  <div class=\"b3__fld\"><label for=\"f7-localidade\">Código postal ou localidade</label><input id=\"f7-localidade\" name=\"localidade\" type=\"text\" autocomplete=\"off\" required aria-required=\"true\" aria-describedby=\"f7-localidade-erro\"><p class=\"b3__err\" id=\"f7-localidade-erro\" hidden></p></div>\n                </div>\n                <div class=\"b3__consent\">\n                  <label class=\"b3__check\"><input type=\"checkbox\" id=\"f7-consentimento\" name=\"consentimento\" required aria-required=\"true\" aria-describedby=\"f7-consentimento-erro f7-rgpd\"><span>Aceito que a TechnoGreen utilize estes dados para responder ao meu pedido de assistência.</span></label>\n                  <p class=\"b3__hint\" id=\"f7-rgpd\">Texto de privacidade (RGPD) a fornecer e validar pela TechnoGreen.</p>\n                  <p class=\"b3__err\" id=\"f7-consentimento-erro\" hidden></p>\n                </div>\n                <div class=\"b3__send\">\n                  <button class=\"btn btn--lime b3__cta\" type=\"submit\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg><span>Enviar pedido de assistência</span></button>\n                  <p class=\"b3__status\" role=\"status\" aria-live=\"polite\" data-f7-status></p>\n                </div>\n              </div>\n            </form>\n          </div>\n          <aside class=\"f7__card\" aria-labelledby=\"f7-card-t\">\n            <p class=\"f7__card-t\" id=\"f7-card-t\">Como pedir assistência</p>\n            <ol class=\"f7__steps\">\n              <li data-f7-done=\"1\"><span class=\"f7__node\" aria-hidden=\"true\"></span><b>Identifique o equipamento</b><span>Diga-nos que equipamento é e, se souber, a marca e o modelo.</span></li>\n              <li data-f7-done=\"2\"><span class=\"f7__node\" aria-hidden=\"true\"></span><b>Descreva o problema</b><span>O que está a acontecer e desde quando.</span></li>\n              <li data-f7-done=\"3\"><span class=\"f7__node\" aria-hidden=\"true\"></span><b>Deixe os seus contactos</b><span>A equipa TechnoGreen analisa o pedido e entra em contacto consigo.</span></li>\n            </ol>\n          </aside>\n        </div>\n      </div>\n    </section>\n\n    <!-- 07 · Perguntas frequentes (versão C, escura) (respostas verificadas em technogreen.pt; as restantes marcadas para validação) -->\n    <section class=\"c-sec c-sec--evening c9\" id=\"perguntas\" aria-labelledby=\"c9-title\" data-station=\"07\" data-label=\"Perguntas frequentes\">\n      <div class=\"b-in\">\n        <p class=\"b-eb b-eb--on-forest\"><b>07</b><span>Perguntas frequentes</span></p>\n        <div class=\"c9__grid\">\n        <div>\n          <h2 class=\"b-h2\" id=\"c9-title\">Antes de decidir.</h2>\n        </div>\n        <div class=\"c9__list\">\n          <details><summary>Os preços dos kits incluem a instalação?</summary><div><p>Sim. Nos kits residenciais, os preços indicados incluem entrega, instalação e IVA.</p></div></details>\n          <details><summary>Posso configurar o meu próprio kit?</summary><div><p>Pode escolher um dos kits disponíveis na loja ou pedir um orçamento com dimensionamento personalizado.</p><p class=\"c-validate\">Redação a validar pela TechnoGreen</p></div></details>\n          <details><summary>O que acontece quando a rede elétrica falha?</summary><div><p>Com um sistema anti-apagão ou Backup-Full, a bateria passa a alimentar os circuitos escolhidos. O que fica ligado depende do sistema instalado. Veja os <a href=\"#anti-apagao\">sistemas anti-apagão</a>.</p><p class=\"c-validate\">Resposta a validar pela TechnoGreen</p></div></details>\n          <details><summary>Como peço um orçamento e dimensionamento?</summary><div><p>Responda às três perguntas do <a href=\"#dimensionamento\">dimensionamento</a>, ou contacte-nos por email para <a href=\"mailto:comercial@technogreen.pt\">comercial@technogreen.pt</a> ou pelo telefone <a href=\"tel:+351964726345\">964&nbsp;726&nbsp;345</a>.</p></div></details>\n          <details><summary>Fazem instalações para empresas?</summary><div><p>Sim. A TechnoGreen tem kits de autoconsumo para empresas.</p><p class=\"c-validate\">Redação a validar pela TechnoGreen</p></div></details>\n        </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- 08 · CTA final (versão C): a linha de energia termina no botão -->\n    <section class=\"c-night c10\" aria-labelledby=\"c10-title\" data-station=\"08\" data-label=\"Pedir dimensionamento\">\n      <div class=\"b-in c10__in\">\n        <p class=\"c10__proof\"><span>30 anos</span> de experiência</p>\n        <h2 class=\"c10__t\" id=\"c10-title\">Peça o dimensionamento do seu sistema.</h2>\n        <div class=\"c10__acts\">\n          <a class=\"btn btn--lime b-cta\" href=\"#dimensionamento\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg><span>Pedir dimensionamento</span></a>\n          <a class=\"b-link b-link--on-forest\" href=\"https://www.technogreen.pt/moduloseestruturas\">Ir para a loja <svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-arrow\"/></svg></a>\n        </div>\n      </div>\n      <span class=\"c10__dawn\" aria-hidden=\"true\"></span>\n    </section>\n  </div></div></div>";
