      loadFonts(base);
      const root = this.shadowRoot || this.attachShadow({ mode: "open" });
      // Cada ligação começa de um markup limpo: nada fica duplicado se o Wix retirar e voltar a pôr o elemento
      root.innerHTML = `<style>${TG_CSS}</style>${TG_HTML.split("__ASSETS__/").join(base)}`;
